<div class="page-actions"><div><h2>Volunteer Registration Management</h2><p>Review and manage new volunteer registrations in a dedicated approval workflow. Approval activates portal access and creates the permanent Volunteer ID and verification QR.</p></div><form method="get" action="<?=url('admin/volunteers/applications')?>" class="admin-search-form"><input name="q" value="<?=e($q??'')?>" placeholder="Search applicant name, email or mobile"><button class="outline-link">Search</button></form></div>
<section class="application-summary-row"><div class="admin-panel queue-stat"><span>⌛</span><div><b><?=number_format((int)($pagination['total']??0))?></b><small>Pending Applications</small></div></div><div class="admin-panel queue-note"><b>Approval workflow</b><small>Review applicant details → approve or reject → approved volunteer receives portal access, ID and QR verification.</small></div></section>
<section class="admin-panel table-panel application-table"><div class="table-wrap"><table><thead><tr><th>Applicant</th><th>Contact</th><th>Profile</th><th>Applied</th><th>Status</th><th>Decision</th></tr></thead><tbody><?php foreach($volunteers as $v):$legacy=empty($v['user_id']);?><tr><td><div class="person-cell"><?php if(!empty($v['profile_photo'])):?><img src="<?=e(public_upload($v['profile_photo']))?>" alt=""><?php else:?><span><?=e(strtoupper(substr($v['full_name'],0,1)))?></span><?php endif;?><div><b><?=e($v['full_name'])?></b><small><?=e($v['occupation']?:'Volunteer applicant')?></small></div></div></td><td><b><?=e($v['email'])?></b><small><?=e($v['mobile'])?></small></td><td><small><?=e($v['city']?:'')?><?=($v['city']&&$v['country'])?', ':''?><?=e($v['country']?:'')?></small><small><?=e(mb_strimwidth((string)($v['skills']??''),0,90,'…'))?></small></td><td><?=e(date('d M Y',strtotime($v['created_at'])))?><small><?=e(date('H:i',strtotime($v['created_at'])))?></small></td><td><span class="status-badge pending">Pending Review</span></td><td><div class="application-actions"><form method="post" action="<?=url('admin/volunteers/status')?>" class="application-approve-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$v['id']?>"><input type="hidden" name="status" value="active"><input type="hidden" name="return_to" value="applications"><?php if($legacy):?><input type="password" name="portal_password" minlength="10" required placeholder="Portal password for legacy record"><?php endif;?><button class="approve">✓ Approve</button></form><form method="post" action="<?=url('admin/volunteers/status')?>" data-confirm="Reject this volunteer application?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$v['id']?>"><input type="hidden" name="status" value="rejected"><input type="hidden" name="return_to" value="applications"><button class="reject">× Reject</button></form></div></td></tr><?php endforeach;?><?php if(!$volunteers):?><tr><td colspan="6" class="empty">No pending volunteer applications found.</td></tr><?php endif;?></tbody></table></div></section>
<?=admin_pagination($pagination??[])?>
